<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$title=trim($_POST['title']??'');$excerpt=trim($_POST['excerpt']??'');$content=trim($_POST['content']??'');$status=($_POST['status']??'draft')==='published'?'published':'draft';if($title&&$content){$slug=slugify($title).'-'.substr(bin2hex(random_bytes(3)),0,5);$pdo->prepare('INSERT INTO articles(title,slug,excerpt,content,status) VALUES(?,?,?,?,?)')->execute([$title,$slug,$excerpt,$content,$status]);set_flash('success','Artikel berhasil dibuat.');}}elseif($action==='toggle'){$pdo->prepare("UPDATE articles SET status=IF(status='published','draft','published') WHERE id=?")->execute([$id]);set_flash('success','Status artikel diperbarui.');}elseif($action==='delete'){$pdo->prepare('DELETE FROM articles WHERE id=?')->execute([$id]);set_flash('success','Artikel dihapus.');}redirect('articles');}
$items=$pdo->query('SELECT * FROM articles ORDER BY created_at DESC')->fetchAll();$flash=get_flash();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Artikel — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head"><span class="eyebrow">Administrator</span><h1 class="page-title">Artikel & panduan</h1><p class="subtitle">Bagikan wawasan kepada komunitas kreator.</p></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="creator-studio"><section class="panel"><h2>Tulis artikel</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field"><label>Judul</label><input name="title" required maxlength="160"></div><div class="field"><label>Ringkasan</label><textarea name="excerpt" rows="2" maxlength="300"></textarea></div><div class="field"><label>Isi artikel</label><textarea name="content" rows="9" required></textarea></div><div class="field"><label>Status</label><select name="status"><option value="draft">Draf</option><option value="published">Terbitkan</option></select></div><button class="btn btn-primary">Simpan artikel</button></form></section><section class="studio-list"><?php foreach($items as $item):?><article class="studio-item article-admin-item"><div class="category-icon">Aa</div><div><span class="visibility <?=$item['status']==='published'?'visibility-public':'visibility-unlisted'?>"><?=e($item['status'])?></span><h3><?=e($item['title'])?></h3><p><?=date('d M Y',strtotime($item['created_at']))?></p><div class="template-actions"><?php if($item['status']==='published'):?><a class="btn btn-secondary btn-sm" href="article/<?=e($item['slug'])?>">Buka</a><?php endif?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-secondary btn-sm"><?=$item['status']==='published'?'Jadikan draf':'Terbitkan'?></button></form></div></div><form method="post" data-confirm="Hapus artikel ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></article><?php endforeach?></section></div></main><footer class="footer">Semarakin · Apins Digital</footer></body></html>
